#!/usr/bin/env python3
"""Offline SIP identity boundary processor (identity boundary protocol, revision 1).

Reads one JSON batch object on stdin, writes one JSON object with per-job results
on stdout.  All parsing is strict per PROTOCOL.md; syntax failures precede
authentication and identity failures.
"""

import json
import sys

ANONYMOUS = "sip:anonymous@anonymous.invalid"
MAX_TEXT = 32768
MAX_PHYS = 512
MAX_LOGICAL = 128
MAX_CSEQ = 2147483647

_L = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
_D = "0123456789"
TOKSET = frozenset(_L + _D + "-.!%*_+`'~")
USERSET = frozenset(_L + _D + "-_.!~*'()+")
ALNUMSET = frozenset(_L + _D)
DIGITSET = frozenset(_D)
HEXSET = frozenset(_D + "abcdefABCDEF")
CALLIDSET = frozenset(_L + _D + "_.@+-")
OK_HEAD = frozenset(chr(c) for c in range(0x20, 0x7F)) | frozenset("\t")
OK_BODY = OK_HEAD | frozenset("\r\n")
WSCH = " \t"

COMPACT = {"f": "from", "t": "to", "i": "call-id", "l": "content-length",
           "c": "content-type"}
REQUIRED = ("from", "to", "call-id", "cseq", "content-length")
SINGLETON = frozenset(("p-preferred-identity", "remote-party-id", "privacy",
                       "content-type"))


class Reject(Exception):
    def __init__(self, reason):
        Exception.__init__(self)
        self.reason = reason


def bad():
    raise Reject("syntax")


# --------------------------------------------------------------------------- #
#  URI scanning / lexical normalization
# --------------------------------------------------------------------------- #

def scan_host(s, i):
    """Return index just past a valid DNS host starting at i, or -1."""
    n = len(s)
    start = i
    while True:
        t = i
        while i < n and (s[i] in ALNUMSET or s[i] == "-"):
            i += 1
        ln = i - t
        if ln < 1 or ln > 63 or s[t] == "-" or s[i - 1] == "-":
            return -1
        if i >= n:
            break
        if s[i] != ".":
            break
        i += 1
        if i >= n:
            break                              # optional single trailing dot
        c = s[i]
        if c == "." or not (c in ALNUMSET or c == "-"):
            break                              # host ends before this char
    total = i - start
    if s[i - 1] == ".":
        total -= 1
    if total < 1 or total > 253:
        return -1
    return i


def scan_uri(s, i):
    """Return index just past a syntactically valid sip/tel URI, or -1."""
    n = len(s)
    if i + 4 > n:
        return -1
    head = s[i:i + 4].lower()
    if head == "sip:":
        j = i + 4
        start = j
        while j < n:
            c = s[j]
            if c in USERSET:
                j += 1
            elif c == "%":
                if j + 3 > n:
                    return -1
                h = s[j + 1:j + 3]
                if h[0] not in HEXSET or h[1] not in HEXSET:
                    return -1
                if chr(int(h, 16)) not in USERSET:
                    return -1
                j += 3
            else:
                break
        if j == start:
            return -1                          # empty user
        if j >= n or s[j] != "@":
            return -1
        return scan_host(s, j + 1)
    if head == "tel:":
        j = i + 4
        if j >= n or s[j] != "+":
            return -1
        start = j
        j += 1
        while j < n and s[j] in DIGITSET:
            j += 1
        count = j - (start + 1)
        if count < 1 or count > 15 or s[start + 1] == "0":
            return -1
        return j
    return -1


def norm_uri(text):
    """Lexically normalize an already validated URI."""
    if text[:4].lower() == "sip:":
        n = len(text)
        j = 4
        out = []
        while j < n and text[j] != "@":
            c = text[j]
            if c == "%":
                out.append(chr(int(text[j + 1:j + 3], 16)))
                j += 3
            else:
                out.append(c)
                j += 1
        host = text[j + 1:].lower()
        if host.endswith("."):
            host = host[:-1]
        return "sip:" + "".join(out) + "@" + host
    return "tel:" + text[4:].lower()


def scheme_of(uri):
    return uri[:3].lower()


def domain_of(identity):
    if identity[:4].lower() != "sip:":
        return None
    at = identity.find("@", 4)
    if at < 0:
        return None
    return identity[at + 1:]


# --------------------------------------------------------------------------- #
#  Addresses
# --------------------------------------------------------------------------- #

def scan_quoted(s, i):
    """s[i] == '"' -> index just past the closing quote, or -1."""
    n = len(s)
    j = i + 1
    while True:
        if j >= n:
            return -1
        c = s[j]
        if c == "\\":
            if j + 1 >= n:
                return -1
            nc = s[j + 1]
            if nc != "\t" and not (" " <= nc <= "~"):
                return -1
            j += 2
            continue
        if c == '"':
            return j + 1
        j += 1


def parse_angle(s, i):
    """s[i] == '<' -> (uri_text, index past '>')."""
    n = len(s)
    i += 1
    while i < n and s[i] in WSCH:
        i += 1
    j = scan_uri(s, i)
    if j < 0:
        bad()
    uri = s[i:j]
    i = j
    while i < n and s[i] in WSCH:
        i += 1
    if i >= n or s[i] != ">":
        bad()
    return uri, i + 1


def parse_addr(s, allow_params):
    """Parse exactly one address; return (raw_uri_text, tag_or_None)."""
    n = len(s)
    i = 0
    if i < n and s[i] == "<":
        uri, i = parse_angle(s, i)
    elif i < n and s[i] == '"':
        j = scan_quoted(s, i)
        if j < 0:
            bad()                              # unterminated quote / dangling escape
        i = j
        while i < n and s[i] in WSCH:
            i += 1
        if i >= n or s[i] != "<":
            bad()                              # display without an address
        uri, i = parse_angle(s, i)
    else:
        j = 0
        saw_token = False
        while j < n:
            t = j
            while t < n and s[t] in TOKSET:
                t += 1
            if t == j:
                break
            saw_token = True
            j = t
            w = j
            while w < n and s[w] in WSCH:
                w += 1
            if w == j:
                break
            j = w
        if saw_token and j < n and s[j] == "<":
            uri, i = parse_angle(s, j)
        else:
            j = scan_uri(s, 0)
            if j < 0:
                bad()
            uri, i = s[:j], j
    tag = None
    if i < n:
        if not allow_params:
            bad()                              # no header parameters here
        while i < n and s[i] in WSCH:
            i += 1
        if i >= n or s[i] != ";":
            bad()                              # stray text after the address
        i += 1
        while i < n and s[i] in WSCH:
            i += 1
        t = i
        while i < n and s[i] in TOKSET:
            i += 1
        if s[t:i].lower() != "tag":
            bad()                              # unsupported parameter
        while i < n and s[i] in WSCH:
            i += 1
        if i >= n or s[i] != "=":
            bad()
        i += 1
        while i < n and s[i] in WSCH:
            i += 1
        t = i
        while i < n and s[i] in TOKSET:
            i += 1
        if i - t < 1 or i - t > 128:
            bad()
        tag = s[t:i]
        while i < n and s[i] in WSCH:
            i += 1
        if i != n:
            bad()                              # a second parameter or stray text
    return uri, tag


def split_list(value):
    """Split a comma separated address list outside quotes and angle brackets."""
    parts = []
    buf = []
    i = 0
    n = len(value)
    depth = 0
    while i < n:
        c = value[i]
        if c == '"':
            j = scan_quoted(value, i)
            if j < 0:
                return None
            buf.append(value[i:j])
            i = j
            continue
        if c == "<":
            depth += 1
            buf.append(c)
            i += 1
            continue
        if c == ">":
            if depth == 0:
                return None
            depth -= 1
            buf.append(c)
            i += 1
            continue
        if c == "," and depth == 0:
            parts.append("".join(buf))
            buf = []
            i += 1
            continue
        buf.append(c)
        i += 1
    if depth != 0:
        return None
    parts.append("".join(buf))
    return parts


# --------------------------------------------------------------------------- #
#  Header framing and request parsing
# --------------------------------------------------------------------------- #

def parse_cseq(value, method):
    n = len(value)
    i = 0
    while i < n and value[i] in DIGITSET:
        i += 1
    if i == 0:
        bad()
    digits = value[:i]
    j = i
    while j < n and value[j] in WSCH:
        j += 1
    if j == i or value[j:] != method:
        bad()
    trimmed = digits.lstrip("0")
    if not trimmed or len(trimmed) > 10:
        bad()
    number = int(trimmed)
    if number < 1 or number > MAX_CSEQ:
        bad()
    return number


def parse_content_length(value, body_len):
    if not value:
        bad()
    for c in value:
        if c not in DIGITSET:
            bad()
    if (value.lstrip("0") or "0") != str(body_len):
        bad()


def parse_identity_field(value):
    uri, _tag = parse_addr(value, False)
    norm = norm_uri(uri)
    if norm == ANONYMOUS:
        bad()                                  # reserved URI is never a claim
    return norm


def parse_request(text):
    if len(text) > MAX_TEXT:
        bad()
    cut = text.find("\r\n\r\n")
    if cut < 0:
        bad()
    head_block = text[:cut]
    body = text[cut + 4:]
    if not frozenset(body) <= OK_BODY:
        bad()
    if not frozenset(head_block) <= OK_HEAD:
        bad()                                  # bare CR/LF, DEL, controls, non-ASCII
    lines = head_block.split("\r\n")
    request_line = lines[0]
    parts = request_line.split(" ")
    if len(parts) != 3 or parts[2] != "SIP/2.0":
        bad()
    method = parts[0]
    if method != "INVITE" and method != "MESSAGE":
        bad()
    uri_text = parts[1]
    if scan_uri(uri_text, 0) != len(uri_text):
        bad()
    if uri_text[:4].lower() != "sip:":
        bad()
    ruri = norm_uri(uri_text)

    phys = lines[1:]
    if len(phys) > MAX_PHYS:
        bad()

    fields = []                                # unfolded raw field texts
    for line in phys:
        if line[:1] in (" ", "\t"):
            if not fields:
                bad()                          # orphan continuation
            fields[-1] = fields[-1][:-len(line) - 2] + " " + line.lstrip(WSCH) + \
                "" if False else fields[-1] + " " + line.lstrip(WSCH)
        else:
            fields.append(line)
    if len(fields) > MAX_LOGICAL:
        bad()

    seen = {}
    parsed = {}
    pai = []
    for raw in fields:
        n = len(raw)
        i = 0
        while i < n and raw[i] in TOKSET:
            i += 1
        if i == 0:
            bad()                              # empty or illegal field name
        name = raw[:i].lower()
        j = i
        while j < n and raw[j] in WSCH:
            j += 1
        if j >= n or raw[j] != ":":
            bad()
        value = raw[j + 1:].strip(WSCH)
        name = COMPACT.get(name, name)
        seen[name] = seen.get(name, 0) + 1
        if seen[name] > 1 and (name in REQUIRED or name in SINGLETON
                               or name == "p-asserted-identity" and False):
            bad()
        if name in SINGLETON and seen[name] > 1:
            bad()
        if name == "from" and seen[name] == 1:
            uri, tag = parse_addr(value, True)
            parsed["from_uri"] = norm_uri(uri)
            parsed["from_tag"] = tag
        elif name == "to" and seen[name] == 1:
            uri, tag = parse_addr(value, True)
            if tag is not None and uri is None:
                bad()
            parsed["to_uri"] = norm_uri(uri)
            parsed["to_tag"] = tag
        elif name == "call-id" and seen[name] == 1:
            if not (1 <= len(value) <= 128):
                bad()
            for c in value:
                if c not in CALLIDSET:
                    bad()
            parsed["call_id"] = value
        elif name == "cseq" and seen[name] == 1:
            parsed["cseq"] = parse_cseq(value, method)
        elif name == "content-length" and seen[name] == 1:
            parse_content_length(value, len(body))
        elif name == "content-type" and seen[name] == 1:
            if not value:
                bad()
            parsed["content_type"] = value
        elif name == "privacy" and seen[name] == 1:
            low = value.lower()
            if low == "id":
                parsed["privacy_id"] = True
            elif low == "none":
                parsed["privacy_id"] = False
            else:
                bad()
        elif name == "p-preferred-identity" and seen[name] == 1:
            parsed["ppi"] = parse_identity_field(value)
        elif name == "remote-party-id" and seen[name] == 1:
            parsed["rpid"] = parse_identity_field(value)
        elif name == "p-asserted-identity":
            members = split_list(value)
            if members is None:
                bad()
            for m in members:
                m = m.strip(WSCH)
                if not m:
                    bad()                      # empty list member
                pai.append(parse_identity_field(m))

    for name in REQUIRED:
        if seen.get(name, 0) != 1:
            bad()
    parsed["pai"] = pai
    parsed["has_pai"] = any(k == "p-asserted-identity" for k in seen)
    if parsed["has_pai"]:
        if len(pai) > 2:
            bad()
        if len(pai) == 2 and scheme_of(pai[0]) == scheme_of(pai[1]):
            bad()
    parsed["method"] = method
    parsed["ruri"] = ruri
    parsed["body"] = body
    parsed.setdefault("content_type", None)
    parsed.setdefault("ppi", None)
    parsed.setdefault("rpid", None)
    parsed.setdefault("privacy_id", False)
    return parsed


# --------------------------------------------------------------------------- #
#  Policy
# --------------------------------------------------------------------------- #

class Context(object):
    def __init__(self, batch):
        self.alias = {}
        directory = batch.get("directory")
        if isinstance(directory, dict):
            for canon, aliases in directory.items():
                if not isinstance(canon, str):
                    continue
                self.alias[canon] = canon
                if isinstance(aliases, (list, tuple)):
                    for a in aliases:
                        if isinstance(a, str):
                            self.alias[a] = canon
        self.accounts = batch.get("accounts")
        if not isinstance(self.accounts, dict):
            self.accounts = {}
        self.gateways = batch.get("gateways")
        if not isinstance(self.gateways, dict):
            self.gateways = {}

    def hosted(self, identity, gw):
        domains = gw.get("local_domains") if isinstance(gw, dict) else None
        if not isinstance(domains, (list, tuple)):
            return False
        d = domain_of(identity)
        return d is not None and d in domains

    def allowed(self, identity, subject):
        acc = self.accounts.get(subject)
        if not isinstance(acc, dict):
            return None
        primary = acc.get("primary")
        allow = acc.get("allow")
        pool = set()
        if isinstance(primary, str):
            pool.add(primary)
        if isinstance(allow, (list, tuple)):
            for a in allow:
                if isinstance(a, str):
                    pool.add(a)
        if identity in pool:
            return primary
        return None


def claim_identity(claim, ctx):
    ident = ctx.alias.get(claim)
    if ident is None:
        bad()                                  # unknown claim: no directory identity
    return ident


def handle(job, index, results, ctx):
    if not isinstance(job, dict):
        raise Reject("syntax")
    text = None
    if "raw" in job:
        raw = job.get("raw")
        if not isinstance(raw, str):
            raise Reject("syntax")
        text = raw
    elif "source" in job:
        src = job.get("source")
        if not isinstance(src, int) or isinstance(src, bool) or src < 0 or src >= index:
            raise Reject("upstream")
        prev = results[src] if src < len(results) else None
        if not isinstance(prev, dict) or prev.get("status") != "accept":
            raise Reject("upstream")
        text = prev.get("wire")
        if not isinstance(text, str):
            raise Reject("upstream")
    else:
        raise Reject("syntax")

    gw = ctx.gateways.get(job.get("gateway"))
    req = parse_request(text)

    ingress = job.get("ingress")
    kind = ingress.get("kind") if isinstance(ingress, dict) else None
    private = req["from_uri"] == ANONYMOUS or req["privacy_id"]
    trusted_out = bool(job.get("trusted_out"))

    if kind == "local":
        subject = ingress.get("subject")
        acc = ctx.accounts.get(subject)
        if not isinstance(acc, dict) or not isinstance(acc.get("primary"), str):
            raise Reject("unauthenticated")
        if not isinstance(gw, dict):
            raise Reject("identity")
        primary = acc["primary"]
        allow = acc.get("allow")
        pool = set()
        pool.add(primary)
        if isinstance(allow, (list, tuple)):
            for a in allow:
                if isinstance(a, str):
                    pool.add(a)
        selected = None
        if req["ppi"] is not None:
            ident = claim_identity(req["ppi"], ctx)
            if ident not in pool or not ctx.hosted(ident, gw):
                bad()
            selected = ident
        if req["from_uri"] != ANONYMOUS:
            ident = claim_identity(req["from_uri"], ctx)
            if ident not in pool or not ctx.hosted(ident, gw):
                bad()
            if selected is None:
                selected = ident
        if selected is None:
            ident = claim_identity(primary, ctx)
            if ident not in pool or not ctx.hosted(ident, gw):
                bad()
            selected = ident
        basis = "local"
    elif kind == "peer":
        peers = gw.get("peers") if isinstance(gw, dict) else None
        if not isinstance(peers, dict):
            raise Reject("unauthenticated")
        name = ingress.get("name")
        if name not in peers:
            raise Reject("unauthenticated")
        if not req["has_pai"]:
            raise Reject("unauthenticated")
        authority = peers[name]
        if not isinstance(authority, (list, tuple)):
            authority = ()
        selected = None
        for claim in req["pai"]:
            ident = claim_identity(claim, ctx)
            if selected is None:
                selected = ident
            elif ident != selected:
                bad()                          # claims disagree
        d = domain_of(selected)
        if d is None or d not in authority:
            bad()                              # peer not authoritative
        for claim in (req["from_uri"], req["ppi"], req["rpid"]):
            if claim is None or claim == ANONYMOUS:
                continue
            if claim_identity(claim, ctx) != selected:
                bad()
        basis = "peer"
    else:
        raise Reject("unauthenticated")

    lines = [req["method"] + " " + req["ruri"] + " SIP/2.0"]
    from_uri = ANONYMOUS if private else selected
    line = "From: <" + from_uri + ">"
    if req["from_tag"] is not None:
        line += ";tag=" + req["from_tag"]
    lines.append(line)
    line = "To: <" + req["to_uri"] + ">"
    if req["to_tag"] is not None:
        line += ";tag=" + req["to_tag"]
    lines.append(line)
    lines.append("Call-ID: " + req["call_id"])
    lines.append("CSeq: " + str(req["cseq"]) + " " + req["method"])
    lines.append("Privacy: " + ("id" if private else "none"))
    if (not private) or trusted_out:
        lines.append("P-Asserted-Identity: <" + selected + ">")
    if req["content_type"] is not None:
        lines.append("Content-Type: " + req["content_type"])
    lines.append("Content-Length: " + str(len(req["body"])))
    wire = "\r\n".join(lines) + "\r\n\r\n" + req["body"]
    return {"status": "accept", "identity": selected, "basis": basis,
            "private": bool(private), "wire": wire}


def process(batch):
    if not isinstance(batch, dict):
        return {"results": []}
    ctx = Context(batch)
    jobs = batch.get("jobs")
    if not isinstance(jobs, (list, tuple)):
        jobs = []
    results = []
    for index, job in enumerate(jobs):
        try:
            results.append(handle(job, index, results, ctx))
        except Reject as exc:
            results.append({"status": "reject", "reason": exc.reason})
        except Exception:
            results.append({"status": "reject", "reason": "syntax"})
    return {"results": results}


def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        data = None
    if not isinstance(data, dict):
        out = {"results": []}
    else:
        out = process(data)
    sys.stdout.write(json.dumps(out))
    sys.stdout.write("\n")
    sys.stdout.flush()


if __name__ == "__main__":
    main()
